import React, { useState } from "react";
import axios from "axios";
import { Link } from "react-router-dom";
import "./Auth.css";

const Login = () => {

  const [email, setEmail] = useState("");

  const [password, setPassword] = useState("");

  const [msg, setMsg] = useState("");

  const submit = async (e) => {

    e.preventDefault();

    try {

      const res = await axios.post(

        "http://localhost:5000/api/auth/login",

        {

          email,

          password

        }

      );

      localStorage.setItem(

        "token",

        res.data.token

      );

      localStorage.setItem(

        "role",

        res.data.user.role

      );

      setMsg("Login Success ✅");

    }

    catch (err) {

      setMsg(

        err.response?.data?.message

        ||

        "Login Failed"

      );

    }

  };



  return (

    <div className="auth-container">

      <div className="auth-card">

        <h1>

          Welcome Back

        </h1>

        <p>

          Login to continue

        </p>

        <form onSubmit={submit}>

          <input

            type="email"

            placeholder="Email"

            value={email}

            onChange={(e) =>

              setEmail(

                e.target.value

              )

            }

            required

          />



          <input

            type="password"

            placeholder="Password"

            value={password}

            onChange={(e) =>

              setPassword(

                e.target.value

              )

            }

            required

          />



          <button

            className="main-btn"

            type="submit"

          >

            Login

          </button>

        </form>



        <p

        style={{

        marginTop:"20px"

        }}

        >

        Don't have an account ?



        <Link

        to="/register"

        style={{

        color:"#2563eb",

        textDecoration:"none",

        fontWeight:"bold",

        marginLeft:"8px"

        }}

        >

        Register

        </Link>

        </p>



        <h4>

        {msg}

        </h4>

      </div>

    </div>

  );

};

export default Login;
